    assert_eq!(exact.unwrap(), (work, bytes));
    assert!(!metrics.invalid);
    assert_eq!(metrics.live, 0);
    for (w, b) in [(work - 1, bytes), (work, bytes - 1)] {
        let (result, metrics) = run(function, &automaton, w, b);
        assert!(result.is_err());
        assert!(!metrics.invalid);
        assert_eq!(metrics.live, 0);
    }
}

