    let promotion_fee = size_of::<Result<(), Diagnostic>>()
        + 2 * size_of::<std::collections::BTreeMap<usize, u64>>()
        + size_of::<Targets>()
        + 2 * size_of::<Option<u64>>()
        + 2 * size_of::<(usize, u64)>();
