    eprintln!("singleton-layout old={} new={} one_fee={one_fee} promotion_fee={promotion_fee} node={node}",
        size_of::<std::collections::BTreeMap<usize, u64>>(), size_of::<Targets>());
    eprintln!("outer-label-node old={} new={}",
