                Targets::One {
                    child: 9,
                    weight: 4
                }
            ));
            let selected = budget.physical.as_mut().unwrap().reserve(0).unwrap_err();
            assert_eq!(budget.physical.as_mut().unwrap().reserve(1), Err(selected));
            let at = budget.physical.as_ref().unwrap().charged();
